+function clampMinMatchCount(raw) {
+    const trimmed = String(raw ?? "").trim();
+    if (trimmed === "") {
+        return 1;
+    }
+    const n = parseInt(trimmed, 10);
+    if (!Number.isFinite(n) || n < 1) {
+        return 1;
+    }
+    return Math.min(n, 999999);
+}
